import React from "react";
import "./MyEvents.css";
import headerImage from "../../../assets/MyEventsHeader.png";
import TedTalk from "../../../assets/TedTalk.png";
import GetTogether from "../../../assets/getTogether.jpg";

const MyEvents = () => {
  const events = [
    { 
      id: 1, 
      name: "TED Talk", 
      description: "An inspiring talk featuring innovative ideas worth spreading.",
      date: "2025-10-20", 
      location: "Hall Building", 
      image: TedTalk 
    },
    { 
      id: 2, 
      name: "Get Together", 
      description: "A fun networking night for students and faculty to connect.", 
      date: "2025-11-05", 
      location: "ER Building", 
      image: GetTogether 
    }
  ];

  return (
    <div className="my-events-container">

      {/* HEADER SECTION */}
      <div 
        className="header-image" 
        style={{
          background: `linear-gradient(to bottom, rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)), url(${headerImage}) no-repeat center center`,
          backgroundSize: "cover",
          height: "250px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "white",
          fontSize: "2.5rem",
          fontWeight: "bold"
        }}
      >
        My Events
      </div>

      {/* EVENTS LIST */}
      <div className="events-list-section">
        {events.length === 0 ? (
          <p className="no-events">You haven’t purchased any events yet.</p>
        ) : (
          <div className="event-list">
            {events.map((event) => (
              <div key={event.id} className="event-item">
                <img src={event.image} alt={event.name} className="event-image" />
                <div className="event-details">
                  <h3>{event.name}</h3>
                  <p className="event-description">{event.description}</p>
                  <p className="event-date">📅 {event.date}</p>
                  <p className="event-location">📍 {event.location}</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default MyEvents;
